import hashlib
import hmac
import json

import requests
from config import (
    BOT_BUILD_LABEL,
    LINEAR_WEBHOOK_MAX_AGE_HOURS,
    LINEAR_WEBHOOK_SECRET_NAME,
)
from utils.boto import get_raw_secret, get_routine_creds
from utils.exceptions import PokedexException
from utils.linear import get_issue_build_context, post_issue_comment
from utils.logutil import getLogger
from utils.routine import fire_routine
from utils.utils import get_header, now, verify_token

logger = getLogger()

LINEAR_SIGNATURE_HEADER = "Linear-Signature"
# stamped on the issue the moment a build is fired. it is both the receipt a human
# reads and the thing that stops a redelivery of the same event building twice
FIRED_MARKER = "<!-- bot-build-fired -->"


def verify_linear_signature(raw_body, headers):
    received = get_header(headers, LINEAR_SIGNATURE_HEADER)
    secret = get_raw_secret(LINEAR_WEBHOOK_SECRET_NAME)
    expected = hmac.new(
        secret.encode("utf-8"), raw_body.encode("utf-8"), hashlib.sha256
    ).hexdigest()
    return verify_token(received, expected)


def delivery_is_fresh(payload):
    # webhookTimestamp is unix milliseconds
    sent_at = payload["webhookTimestamp"] / 1000
    age_hours = (now().timestamp() - sent_at) / 3600
    return age_hours < LINEAR_WEBHOOK_MAX_AGE_HOURS


def bot_build_label(issue):
    for label in issue["labels"]:
        if label["name"] == BOT_BUILD_LABEL:
            return label
    return None


def already_fired(issue):
    for comment in issue["comments"]:
        if FIRED_MARKER in comment:
            return True
    return False


def build_routine_text(issue):
    return json.dumps(
        {
            "linear_issue_url": issue["url"],
            "linear_issue_identifier": issue["identifier"],
            "title": issue["title"],
            "description": issue["description"],
        }
    )


def fire_build(issue):
    creds = get_routine_creds("plan-integration")
    try:
        result = fire_routine(creds, build_routine_text(issue))
    except requests.RequestException as e:
        # no marker is stamped, so Linear's retry gets a clean second attempt
        raise PokedexException(
            f"Failed to fire plan-integration for {issue['identifier']}: {e}",
            502,
            origin="trackstar",
        )
    session_url = result.get("claude_code_session_url")
    try:
        post_issue_comment(
            issue["id"],
            f"{FIRED_MARKER}\nBuilding this integration: [session]({session_url})",
        )
    except (PokedexException, requests.RequestException) as e:
        # the build is already running; losing the stamp only weakens the dedup
        logger.warning(f"failed to stamp bot-build comment on {issue['id']}: {e}")
    return {
        "session_id": result.get("claude_code_session_id"),
        "session_url": session_url,
    }


def handle_linear_webhook(payload):
    if payload["type"] != "Issue":
        return {"fired": False, "reason": f"not an issue event ({payload['type']})"}
    if not delivery_is_fresh(payload):
        return {"fired": False, "reason": "delivery too old"}
    if payload["action"] not in ["create", "update"]:
        return {"fired": False, "reason": f"nothing to build on a {payload['action']}"}
    # on an update Linear sends the fields that changed and their old values, so a
    # payload with no labels in it is an edit that never touched them
    updated_from = payload.get("updatedFrom") or {}
    if payload["action"] == "update" and "labelIds" not in updated_from:
        return {"fired": False, "reason": "the labels didn't change"}

    issue = get_issue_build_context(payload["data"]["id"])
    label = bot_build_label(issue)
    if not label:
        return {"fired": False, "reason": f"no {BOT_BUILD_LABEL} label on the issue"}
    # build when the label goes on, not on later edits to an issue that already has it
    if label["id"] in (updated_from.get("labelIds") or []):
        return {"fired": False, "reason": f"{BOT_BUILD_LABEL} was already on the issue"}
    if already_fired(issue):
        return {"fired": False, "reason": "already built"}

    fired = fire_build(issue)
    logger.info(f"fired plan-integration for {issue['identifier']}: {fired}")
    return {"fired": True, "identifier": issue["identifier"], **fired}

